package net.officefloor.hq.app.rate;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** The rate for each grade on a sheet. */
@RestController
@RequestMapping("/api/sheets/{sheetId}/rates")
public class RateController {

    /** The rate is a percent, 0.00 or more, with up to two decimals; no from-date means from the beginning
     * of time. */
    public record RateForm(@NotNull @Pattern(regexp = "\\d{1,3}(\\.\\d{1,2})?") String rate, LocalDate from) {}

    /** The rate is shown with two decimals. */
    public record RateView(String grade, LocalDate from, String rate) {

        static RateView of(Rate rate) {
            return new RateView(rate.getGrade(), rate.getFrom(), rate.getRate().setScale(2).toPlainString());
        }
    }

    private final RateService service;

    public RateController(RateService service) {
        this.service = service;
    }

    @GetMapping
    public List<RateView> list(@RequestHeader("X-User") String user, @PathVariable String sheetId) {
        return service.list(sheetId).stream().map(RateView::of).toList();
    }

    @PutMapping("/{grade:[ABC]}")
    public RateView set(@RequestHeader("X-User") String user, @PathVariable String sheetId,
            @PathVariable String grade, @Valid @RequestBody RateForm form) {
        return RateView.of(service.set(user, sheetId, grade, form.from(), new BigDecimal(form.rate())));
    }
}
package net.officefloor.hq.app.rate;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Collection;
import java.util.Comparator;
import java.util.Optional;

/** A rate for a grade on a sheet: a percent with two decimals, in force from its from-date (or from the
 * beginning of time when it has none). */
@Entity
@Table(name = "rate")
public class Rate {

    /** Rates by from-date, the one with no from-date first. */
    public static final Comparator<Rate> BY_FROM =
            Comparator.comparing(Rate::getFrom, Comparator.nullsFirst(Comparator.naturalOrder()));

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "grade", nullable = false)
    private String grade;

    @Column(name = "from_date")
    private LocalDate from;

    @Column(name = "rate", nullable = false, precision = 5, scale = 2)
    private BigDecimal rate;

    protected Rate() {}

    public Rate(String sheetId, String grade, LocalDate from, BigDecimal rate) {
        this.sheetId = sheetId;
        this.grade = grade;
        this.from = from;
        this.rate = rate;
    }

    /** Of a grade's rates, the one in force on a date: the latest from-date on or before it; none when the
     * date is before every one. */
    public static Optional<Rate> inForce(Collection<Rate> rates, LocalDate date) {
        return rates.stream()
                .filter(r -> r.getFrom() == null || !r.getFrom().isAfter(date))
                .max(BY_FROM);
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getGrade() {
        return grade;
    }

    public LocalDate getFrom() {
        return from;
    }

    public BigDecimal getRate() {
        return rate;
    }

    public void setRate(BigDecimal rate) {
        this.rate = rate;
    }
}
package net.officefloor.hq.app.rate;

import java.time.LocalDate;
import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;

public interface RateRepository extends JpaRepository<Rate, Long> {

    /** The sheet's rates. */
    List<Rate> findBySheetId(String sheetId);

    /** A grade's rates on the sheet. */
    List<Rate> findBySheetIdAndGrade(String sheetId, String grade);

    /** A grade's rate from a from-date; a null from-date finds the one with none. */
    Optional<Rate> findBySheetIdAndGradeAndFrom(String sheetId, String grade, LocalDate from);
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.rollup.RollupService.Snapshot;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class RateService {

    private final RateRepository rates;
    private final SheetService sheets;
    private final RollupService rollup;
    private final Audit audit;

    public RateService(RateRepository rates, SheetService sheets, RollupService rollup, Audit audit) {
        this.rates = rates;
        this.sheets = sheets;
        this.rollup = rollup;
        this.audit = audit;
    }

    /** The sheet's rates by grade, then from-date; a grade without one has no rate. */
    @Transactional(readOnly = true)
    public List<Rate> list(String sheetId) {
