import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';
import { Session } from '../../core/session';
import { Grade } from '../people/people-api';

export interface Rate {
  grade: Grade;
  /** The date (yyyy-mm-dd) the rate is in force from; null for from the beginning of time. */
  from: string | null;
  /** A percent with two decimals, e.g. "12.50". */
  rate: string;
}

/**
 * The rate a grade has in force on a date (yyyy-mm-dd): the one with the latest from-date on or
 * before it; none when the date is before every rate of the grade.
 */
export function rateOn(rates: readonly Rate[], grade: Grade, date: string): string | undefined {
  // No from-date sorts as '', before every date.
  let best: Rate | undefined;
  for (const r of rates) {
    const from = r.from ?? '';
    if (r.grade === grade && from <= date && (!best || from > (best.from ?? ''))) best = r;
  }
  return best?.rate;
}

/** Shown in place of a due whose grade has no rate. */
export const NO_RATE = 'n/a';

/** Hundredths of a decimal with up to two decimals, e.g. "12.5" is 1250. */
function hundredths(value: string): bigint {
  const [whole, frac = ''] = value.split('.');
  return BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0'));
}

/**
 * What is due on an amount at a rate: the amount times the rate, divided by 100, rounded half to
 * even to two decimals. Worked in whole numbers so no rounding creeps in; n/a when there is no rate.
 */
export function dueOf(amount: string, rate: string | undefined): string {
  if (rate === undefined) return NO_RATE;
  // cents × hundredths of a percent is in ten-thousandths of a cent; round to cents, a half to the even
  // cent (amounts are never negative).
  const exact = hundredths(amount) * hundredths(rate);
  const rest = exact % 10000n;
  let cents = exact / 10000n;
  if (rest > 5000n || (rest === 5000n && cents % 2n === 1n)) cents += 1n;
  return `${cents / 100n}.${String(cents % 100n).padStart(2, '0')}`;
}

// The rate for each grade on the active sheet, read and changed through the server.
@Injectable({ providedIn: 'root' })
export class RatesApi {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  list(sheetId: string): Observable<Rate[]> {
    return this.http.get<Rate[]>(this.url(sheetId), { headers: this.headers() });
  }

  set(sheetId: string, grade: Grade, rate: string, from: string | null): Observable<Rate> {
    return this.http.put<Rate>(`${this.url(sheetId)}/${grade}`, { rate, from }, { headers: this.headers() });
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/rates`;
  }

  private headers(): Record<string, string> {
    return { 'X-User': this.session.user() ?? '' };
  }
}
import { Component, computed, inject, input, output, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { Session } from '../../core/session';
import { Grade } from '../people/people-api';
import { NO_RATE, Rate, RatesApi } from './rates-api';

const PCT = /^\d{1,3}(\.\d{1,2})?$/;
const DATE = /^\d{4}-\d{2}-\d{2}$/;

/** A row of the rate list: a grade's rate from a from-date, or from the start when it has none. */
interface RateRow {
  key: string;
  grade: Grade;
  from: string | null;
  rate: string | undefined;
}

// The rates for each grade on the sheet, each from its from-date, the rate each grade has in force
// on the sheet's today, and the form that sets one.
@Component({
  selector: 'app-rates',
  imports: [ReactiveFormsModule],
  template: `
    <section aria-labelledby="rates-heading" data-testid="rates">
      <h2 id="rates-heading">Rates</h2>
      <form [formGroup]="form" (ngSubmit)="submit()" data-testid="rate-form">
        <label for="rate-form-grade">Grade</label>
        <select id="rate-form-grade" data-testid="rate-form-grade" formControlName="grade">
          @for (g of grades(); track g) {
            <option [value]="g">{{ g }}</option>
          }
        </select>
        <label for="rate-form-pct">Rate (%)</label>
        <input id="rate-form-pct" data-testid="rate-form-pct" inputmode="decimal" formControlName="pct" />
        <label for="rate-form-from">From (optional)</label>
        <input id="rate-form-from" data-testid="rate-form-from" type="date" formControlName="from" />
        <button type="submit" data-testid="rate-form-submit">Set rate</button>
      </form>
      @if (formError(); as e) {
        <p role="alert" data-testid="rate-form-error">{{ e }}</p>
      }
      <table data-testid="rate-current-list">
        <caption>In force on {{ session.today() ?? '' }}</caption>
        <thead>
          <tr>
            <th scope="col">Grade</th>
            <th scope="col">Rate (%)</th>
          </tr>
        </thead>
        <tbody>
          @for (g of grades(); track g) {
            <tr>
              <td>{{ g }}</td>
              <td [attr.data-testid]="'rate-current-' + g">{{ current().get(g) ?? noRate }}</td>
            </tr>
          }
        </tbody>
      </table>
      <table data-testid="rate-list">
        <thead>
          <tr>
            <th scope="col">Grade</th>
            <th scope="col">From</th>
            <th scope="col">Rate (%)</th>
          </tr>
        </thead>
        <tbody>
          @for (r of rows(); track r.key) {
            <tr [attr.data-testid]="'rate-row-' + r.key">
              <td data-testid="rate-grade">{{ r.grade }}</td>
              <td data-testid="rate-from">{{ r.from ?? 'Start' }}</td>
              <td data-testid="rate-pct">
                @if (saving() === r.key) {
                  Saving…
                } @else {
                  {{ r.rate ?? noRate }}
                }
              </td>
            </tr>
          }
        </tbody>
      </table>
    </section>
  `,
})
export class Rates {
  protected readonly session = inject(Session);
  private readonly api = inject(RatesApi);

  readonly grades = input.required<Grade[]>();
  /** The sheet's rates. */
  readonly rates = input.required<readonly Rate[]>();
  /** The rate each grade with one has in force on the sheet's today. */
  readonly current = input.required<ReadonlyMap<Grade, string>>();
  /** A rate was set. */
  readonly saved = output<Rate>();

  protected readonly noRate = NO_RATE;
  /** Each grade's rate from the start (n/a when it has none), then its rates by from-date. */
  protected readonly rows = computed<RateRow[]>(() =>
    this.grades().flatMap((grade) => {
      const own = this.rates().filter((r) => r.grade === grade);
      const dated = own
        .filter((r) => r.from !== null)
        .sort((a, b) => (a.from! < b.from! ? -1 : 1))
        .map((r) => ({ key: rowKey(grade, r.from), grade, from: r.from, rate: r.rate }));
      const start = own.find((r) => r.from === null);
      return [{ key: rowKey(grade, null), grade, from: null, rate: start?.rate }, ...dated];
    }),
  );
  /** The row whose rate is being saved, shown as such until the store has it. */
  protected readonly saving = signal<string | null>(null);
  protected readonly formError = signal<string | null>(null);
  protected readonly form = new FormGroup({
    grade: new FormControl<Grade>('A', { nonNullable: true }),
